// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address to1, address to2, uint256 a1, uint256 a2) public {
        // Admissible domain: two distinct recipients and a nonzero amount for the second
        // so that v[0] != v[1] is achievable; keep it wide otherwise.
        vm.assume(to1 != to2);
        vm.assume(a2 != a1);

        Recorder rec = new Recorder();
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        uint256[] memory v = new uint256[](2);
        v[0] = a1;
        v[1] = a2;

        // The helper accepts every transferFrom call and accumulates the observed amounts.
        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool r) { ok = r; } catch { ok = false; }

        // General rule: whenever transfer succeeds, the counterparty must have observed the
        // exact per-index amounts, i.e. total observed == a1 + a2 (overflow-safe comparison via equality
        // of both the count and the accumulated sum, and also the individual recorded amounts match).
        // The mutant sends a1 for both indices, so observed total == 2*a1 != a1+a2 when a1 != a2.
        bool referenceHolds = (!ok)
            || (rec.calls() == 2 && rec.total() == a1 + a2 && rec.at(0) == a1 && rec.at(1) == a2);
        assertTrue(referenceHolds);
    }
}

contract Recorder {
    uint256 public calls;
    uint256 public total;
    uint256[] internal seen;

    function transferFrom(address, address, uint256 amount) external returns (bool) {
        calls += 1;
        total += amount;
        seen.push(amount);
        return true;
    }

    function at(uint256 i) external view returns (uint256) {
        return seen[i];
    }
}
